/**
 * @name Server-Side Template Injection via unsafe template rendering
 * @description User-controlled input flowing into Jinja2 template compilation or rendering can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/jinja2-ssti
 * @tags security
 *        external/cwe/cwe-094
 *        external/cwe/cwe-1336
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SSTIConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        // Template.render() or Template.generate()
        call = API::moduleImport("jinja2").getMember("Template").getReturn().getMember(["render", "generate", "render_async", "generate_async"]).getACall() and
        sink = call.getArg(0)
        or
        // Environment.from_string() - compiles template from string
        call = API::moduleImport("jinja2").getMember("Environment").getReturn().getMember("from_string").getACall() and
        sink = call.getArg(0)
        or
        // Template() constructor - direct template compilation
        call = API::moduleImport("jinja2").getMember("Template").getACall() and
        sink = call.getArg(0)
      )
    )
  }
}

module SSTIFlow = TaintTracking::Global<SSTIConfig>;
import SSTIFlow::PathGraph

from SSTIFlow::PathNode source, SSTIFlow::PathNode sink
where SSTIFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Server-Side Template Injection: user input flows into template $@.", source.getNode(), "from user input"

/**
 * @name Path traversal in template loading
 * @description User-controlled template names may allow access to files outside intended directories
 * @kind path-problem
 * @problem.severity error
 * @id py/jinja2-path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // Template loading methods
      call.getFunction().(DataFlow::AttrRead).getAttributeName() in ["get_template", "select_template", "get_or_select_template", "load"] and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Template name from $@ may allow path traversal.", source.getNode(), "user input"
